    "actions-146": {prompt:"A lista do chamador permite uma ação privada, mas outro repositório privado ainda não consegue usá-la. O que verificar separadamente?",choices:["O título das notas.","Retenção de artefatos.","A política Actions do repositório-fonte que permite compartilhar acesso.","Quantidade de entradas."],explanations:["O título não concede acesso.","Retenção não autoriza baixar código.","Permitir uso e acesso à fonte privada são requisitos distintos.","Entradas não controlam compartilhamento."],concept:"Acesso versus uso permitido",hints:["Permitir executar implica permitir recuperar código?","Qual repositório controla a privacidade da implementação?"]},
    "actions-147": {prompt:"Como centralizar um workflow reutilizável e permitir adoção deliberada de atualizações revisadas?",choices:["Copiá-lo todo dia.","Guardar YAML somente numa issue.","Usar uma branch pessoal sem revisão.","Chamar a fonte central por versão ou commit revisado e atualizar referências com revisão."],explanations:["Cópias criam definições independentes.","Issues não são fontes executáveis.","Uma branch móvel sem revisão prejudica controle.","Chamadas versionadas combinam centralização e atualização controlada."],concept:"Distribuição reutilizável controlada",hints:["Como compartilhar implementação sem perder controle das atualizações?","Qual mudança de dependência deve aparecer num diff revisável?"]},
